style.css:
@-moz-document domain("chat.openai.com") {
/* Fondo general */
    body, html, #__next {
        background-color: #0a192f !important;  /* azul oscuro */
        color: #dbe5f1 !important;             /* texto azul-grisáceo */
    }

    /* Área principal del chat */
    main {
        background-color: #112240 !important;  /* azul apagado */
    }

    /* Mensajes (bloques de texto) */
    .prose {
        background-color: #1b2b4b !important;
        border-radius: 10px !important;
        padding: 8px 12px !important;
        color: #e0e6ed !important;
    }

    /* Caja para escribir mensaje */
    textarea {
        background-color: #0d1b2a !important;
        color: #e0e6ed !important;
        border: 1px solid #1e3a5f !important;
        border-radius: 8px !important;
        padding: 8px !important;
    }

    /* Botones */
    button {
        background-color: #1e3a5f !important;
        color: #f0f6fc !important;
        border-radius: 6px !important;
        border: none !important;
        padding: 6px 12px !important;
    }

    button:hover {
        background-color: #2c4f7a !important;
    }

    /* Scrollbar personalizado */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-thumb {
        background-color: #1e3a5f !important;
        border-radius: 10px;
    }
    ::-webkit-scrollbar-track {
        background-color: #0a192f !important;
    }
}
